const {THREE,sim,world,view,camera}=game;
const originalGravity={x:world.gravity.x,y:world.gravity.y,z:world.gravity.z};
const originalActive=sim.inventionActive;
let moon=false,time=0,disposed=false;
const ringGroup=new THREE.Group();
ringGroup.name='Moon remote halo';
view.invention.add(ringGroup);
const ringGeometry=new THREE.TorusGeometry(.245,.012,8,64);
const ringMaterial=new THREE.MeshBasicMaterial({color:0xffb85c,transparent:true,opacity:.35,depthTest:false,depthWrite:false});
const ring=new THREE.Mesh(ringGeometry,ringMaterial);
ring.name='Gravity status ring';
ring.rotation.x=Math.PI/2;
ring.renderOrder=20;
ringGroup.add(ring);
const beadGeometry=new THREE.SphereGeometry(.024,10,8);
const beadMaterial=new THREE.MeshBasicMaterial({color:0xe0ffff,depthTest:false,depthWrite:false});
const bead=new THREE.Mesh(beadGeometry,beadMaterial);
bead.renderOrder=21;
ringGroup.add(bead);
const heldRotation=new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,1,0),Math.PI/2);
function show(){
 ringGroup.position.set(.65,moon?-.23+Math.sin(time*2.6)*.035:-.34,.3);
 ringGroup.rotation.set(moon?Math.sin(time)*.16:0,moon?time*.8:0,moon?.18:0);
 ringMaterial.color.setHex(moon?0x65eeff:0xffb85c);
 ringMaterial.opacity=moon?.9:.35;
 bead.visible=moon;
 bead.position.set(Math.cos(time*2)*.245,0,Math.sin(time*2)*.245);
}
function gravity(){world.gravity={x:originalGravity.x*(moon?1/6:1),y:originalGravity.y*(moon?1/6:1),z:originalGravity.z*(moon?1/6:1)};}
show();
return {
 use(){
  if(disposed)return;
  moon=!moon;
  sim.inventionActive=moon;
  gravity();
  world.forEachRigidBody(body=>{if(body.isDynamic())body.wakeUp();});
  show();
  game.say(moon?'MOON GRAVITY — jump higher, drift down slowly.':'NORMAL GRAVITY — feet back on Earth.');
  game.sound(moon?320:640,.16,.07,moon?850:200);
 },
 step(dt){
  if(disposed)return;
  time+=dt;
  sim.inventionActive=moon;
  if(moon){
   // Remove the controller’s extra heavy-fall force, including on the first toggled frame.
   // The ordinary jump launch stays unchanged; reduced gravity supplies real extra height and airtime.
   sim.player.resetForces(true);
  }
  show();
 },
 render(){
  if(disposed)return;
  if(view.firstPerson!==false){
   view.invention.position.copy(camera.position);
   view.invention.quaternion.copy(camera.quaternion).multiply(heldRotation);
  }
 },
 dispose(){
  if(disposed)return;
  disposed=true;
  world.gravity={...originalGravity};
  sim.inventionActive=originalActive;
  world.forEachRigidBody(body=>{if(body.isDynamic())body.wakeUp();});
  ringGroup.removeFromParent();
  ringGeometry.dispose();ringMaterial.dispose();beadGeometry.dispose();beadMaterial.dispose();
 }
};

