const {sim,world,RAPIER,view}=game;
const normalGravity=world.gravity.y;
sim.autoRun=false;sim.manual={x:0,y:0,z:0};
sim.player.setTranslation({x:-6,y:.8,z:0},true);
sim.player.setLinvel({x:0,y:0,z:0},true);
sim.aim={x:1,y:0,z:0};
advance(2);advance(45);
sim.jump();advance(25);
const normalJumpHeight=sim.position.y;
assert(normalJumpHeight>1.4,'Ordinary jump launches physically before toggling');
advance(100);
behavior.use();
assert(Math.abs(world.gravity.y-normalGravity/6)<.001,'F changes global gravity to one sixth');
sim.jump();advance(60);
assert(sim.position.y>normalJumpHeight+2,'Moon gravity produces a substantially higher real jump');
assert(sim.player.linvel().y>2,'Moon jump is still ascending after a full second');
const halo=view.invention.getObjectByName('Gravity status ring');
assert(halo && halo.visible && halo.material.opacity>.8,'Moon mode has a bright visible halo');
const probe=world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(-5,18,1));
world.createCollider(RAPIER.ColliderDesc.ball(.1).setMass(1),probe);
try{
 sim.player.setTranslation({x:-6,y:12,z:0},true);
 sim.player.setLinvel({x:0,y:0,z:0},true);
 advance(2);
 sim.player.setLinvel({x:0,y:0,z:0},true);
 probe.setLinvel({x:0,y:0,z:0},true);
 advance(30);
 const moonFall=sim.player.linvel().y;
 assert(moonFall<-.6 && moonFall>-1.1,'Player falls under actual lunar acceleration');
 assert(Math.abs(probe.linvel().y-normalGravity/12)<.1,'Independent dynamic bodies also experience moon gravity');
 behavior.use();
 assert(Math.abs(world.gravity.y-normalGravity)<.001,'Second F restores normal global gravity');
 sim.player.setTranslation({x:-6,y:12,z:0},true);
 sim.player.setLinvel({x:0,y:0,z:0},true);
 probe.setLinvel({x:0,y:0,z:0},true);
 advance(30);
 assert(sim.player.linvel().y<moonFall*4,'Normal mode restores the much faster ordinary fall');
 assert(Math.abs(probe.linvel().y-normalGravity/2)<.1,'Normal gravity is restored for other bodies too');
 assert(halo.material.opacity<.5,'Halo visibly returns to its dim normal state');
 behavior.use();behavior.use();
 assert(Math.abs(world.gravity.y-normalGravity)<.001,'Every press toggles, including rapid consecutive presses');
}finally{world.removeRigidBody(probe);}
